#include <set>
#include <list>

void sequence_erase(std::list<int>& l, std::list<int>::iterator pos) {
    // Sequence container: returns iterator to successor
    pos = l.erase(pos); 
}

void associative_erase(std::set<int>& s, std::set<int>::iterator pos) {
    // Associative container: returns void (must advance manually or increment before erase)
    // auto next_pos = std::next(pos); // C++11+
    s.erase(pos); 
    // pos is now invalid. Cannot use 'pos = s.erase(pos);'
}
